   ax.set_title(('T1 CE'if contrast_index==0 else 'provided registered T2')+' · '+form+' · '+plane,color='white',fontsize=11);meta.append({'contrast':name,'coordinateForm':form,'plane':plane,'providedSourceIndex':int(focus[n]),'sourceROIcropLowIJK':lo.tolist(),'sourceROIcropHighIJK':hi.tolist(),'window':[float(low),float(high)],'originalImageROIBytesSHA256':sha(original.tobytes()),'renderedPixelSHA256':sha(rgb.tobytes()),'samples':sampled})
